<div x-data="creditCard()" x-ref="creditCard" class='max-w-md mx-auto space-y-6 sp-methods'>

    <div class="w-full max-w-md mx-auto min-w-[200px]">
        <label class="block mb-1 text-sm text-slate-800">
            Nome que está no Cartão
            <input
                name="payment[card_holder]"
                type="text"
                class="w-full h-10 bg-transparent placeholder:text-slate-400 text-slate-700 text-sm border border-slate-200 rounded px-3 py-2 transition duration-300 ease focus:outline-none focus:border-slate-400 hover:border-slate-400 shadow-sm focus:shadow-md"
                placeholder="Exemplo: Fulano da Silva"
            />
        </label>

        <label class="block mb-1 text-sm text-slate-800 card_input">
            Número do Cartão
            <input
                type="text"
                name="payment[card_number]"
                id="cardNumber"
                x-model="cardNumber"
                @input="formatCardNumber(); detectBrand()"
                :maxlength="maxLength"
                class="w-full h-10 bg-transparent placeholder:text-slate-400 text-slate-700 text-sm border border-slate-200 rounded px-3 py-2"
                placeholder="1234 5678 9012 3456"
            />
            <div class="card_brand">
