        <div class="flex">
            <div class="w-full md:w-8/12 mr-4">
                <label class="block mb-1 text-sm text-slate-800">
                    Data de Expiração
                    <input
                        type="text"
                        class="w-full h-10 bg-transparent placeholder:text-slate-400 text-slate-700 text-sm border border-slate-200 rounded px-3 py-2 transition duration-300 ease focus:outline-none focus:border-slate-400 hover:border-slate-400 shadow-sm focus:shadow-md"
                        name="payment[card_expiry]"
                        x-model="expiry"
                        @input="formatExpiry()"
                        placeholder="MM/YYYY"
                        maxlength="7"
                    />
                    <p class="text-red-500 text-sm" x-show="errors.expiry" x-text="errors.expiry"></p>
                </label>
            </div>
            <div class="w-full md:w-4/12">
                <label class="block mb-1 text-sm text-slate-800">
                    CVV
                    <input
                        type="text"
                        name="payment[card_cvv]"
                        x-model="cvv"
                        :maxlength="cvvMaxLength"
                        class="w-full h-10 bg-transparent placeholder:text-slate-400 text-slate-700 text-sm border border-slate-200 rounded px-3 py-2 transition duration-300 ease focus:outline-none focus:border-slate-400 hover:border-slate-400 shadow-sm focus:shadow-md"
                        placeholder="123"
                        maxlength="3"
                        pattern="\d{3}"
                    />
                    <p class="text-red-500 text-sm" x-show="errors.cvv" x-text="errors.cvv"></p>
                </label>
            </div>
        </div>

        <input
            type="hidden"
            name="payment[card_brand]"
            :value="brand"
        >

    </div>

</div>
